window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1134f09373b44cf0"]={"versions": [{"id": "FIG-1134f09373b44cf0", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm zur Einordnung des Geltungsbereichs des Software-Component-Templates (SWC-T) in die AUTOSAR-ECU-Software-Architektur. Das Modell gliedert sich vertikal von oben nach unten in die Anwendungsebene („AUTOSAR Software“), die vermittelnde Laufzeitumgebung („AUTOSAR Runtime Environment (RTE)“), die Basissoftware („Basic Software“) sowie die darunterliegende Steuergeräte-Hardware („ECU-Hardware“). Farbige Schraffur-Umrandungen und eine Legende heben hervor, welche Architekturanteile vollständig oder partiell über das Software-Component-Template spezifiziert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die oberste Schicht umfasst verschiedene Software-Component-Typen („Application Software Component“, „Actuator Software Component“, „Sensor Software Component“), die über „AUTOSAR Interface“-Ports an die darunterliegende RTE angebunden sind. Unterhalb der RTE gliedert sich die Basic Software in:</p>\n<ul class=\"fig-list\"><li>„Operating System“ (angebunden über „Standardized Interface“ zur RTE und intern über vertikales „Standardized Interface“ zu den übrigen BSW-Modulen),\n</li><li>„Services“ (mit oberem „Standardized AUTOSAR Interface“ zur RTE und unterem „Standardized Interface“),\n</li><li>„Communication“ (mit oberen und unteren „Standardized Interface“-Ports),\n</li><li>„ECU Abstraction“ (mit oberem „AUTOSAR Interface“ zur RTE und unterem „Standardized Interface“),\n</li><li>„Microcontroller Abstraction“ (über „Standardized Interface“ mit der ECU Abstraction verbunden),\n</li><li>„Complex Device Drivers“ (über „AUTOSAR Interface“ an die RTE angebunden und mit direktem Durchgriff auf die ECU-Hardware).\n</li></ul>\n<p class=\"fig-p\">Schnittstellentypen:</p>\n<ul class=\"fig-list\"><li>„AUTOSAR Interface“: Schnittstelle zwischen SWCs bzw. bestimmten BSW-Modulen und der RTE (vertikale blaue Doppelpfeile).\n</li><li>„Standardized AUTOSAR Interface“: Spezielle AUTOSAR-Schnittstelle für System-Services an die RTE (blauer Doppelpfeil).\n</li><li>„Standardized Interface“: Interne C-APIs der Basissoftware und zum Betriebssystem (orangefarbene Doppelpfeile zur RTE, grüne Verbindungspfeile innerhalb der BSW).\n</li></ul>\n<p class=\"fig-p\">Legende:</p>\n<ul class=\"fig-list\"><li>Grün vertikal gestreifte Umrandung: Software-Komponenten, die durch das Software-Component-Template vollständig beschrieben werden (Application-, Actuator- und Sensor-SWCs).\n</li><li>Blau diagonal gestreifte Umrandung: Software-Komponenten/BSW-Module, bei denen nur die „AUTOSAR Interface“-Seite im Software-Component-Template vollständig beschrieben werden kann (Services, ECU Abstraction, Complex Device Drivers).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtenarchitektur ohne explizite Ablauf- oder Sequenzpfade. Interaktionsbeziehungen sind über vertikale Doppelpfeile dargestellt:</p>\n<ul class=\"fig-list\"><li>Bidirektionale Interaktion zwischen Software-Komponenten und der RTE über AUTOSAR Interfaces.\n</li><li>Bidirektionale Kommunikation der RTE mit Services, ECU-Abstraktion und Complex Device Drivers über AUTOSAR- bzw. Standardized AUTOSAR Interfaces.\n</li><li>Direkte RTE-Verbindung zu Kommunikationsmodulen und dem Betriebssystem über Standardized Interfaces.\n</li><li>Modulübergreifende horizontale und vertikale Dienstaufrufe innerhalb der Basissoftware über Standardized Interfaces hin zum Betriebssystem und zwischen Abstraktionsschichten.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Abgrenzung des Spezifikationsbereichs für das SoftwareComponentTemplate:</p>\n<ul class=\"fig-list\"><li>Vollständig im Scope des Templates liegen Software-Komponenten der Anwendungsebene (Application, Sensor, Actuator SWCs).\n</li><li>Partiell im Scope liegen BSW-Module mit Service- oder Treibercharakter (Services, ECU Abstraction, CDD), beschränkt auf deren RTE-zugewandte AUTOSAR-Interface-Beschreibung (Service Component, ECU Abstraction Component, Complex Device Driver Component).\n</li><li>Nicht im Scope des SWC-Templates liegen reine interne BSW-Mechanismen, Kommunikationsstapel-Details, das Betriebssystem sowie MCAL-Treiber, sofern sie ausschließlich über Standardized Interfaces interagieren; diese unterliegen dem Basic Software Module Description Template (BSWMDT).\n</li></ul>"}, {"id": "FIG-25f3caeb24489c15", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm zur Einordnung des Geltungsbereichs des Software-Component-Templates (SWC-T) in die AUTOSAR-ECU-Software-Architektur. Das Modell gliedert sich vertikal von oben nach unten in die Anwendungsebene („AUTOSAR Software“), die vermittelnde Laufzeitumgebung („AUTOSAR Runtime Environment (RTE)“), die Basissoftware („Basic Software“) sowie die darunterliegende Steuergeräte-Hardware („ECU-Hardware“). Farbige Schraffur-Umrandungen und eine Legende heben hervor, welche Architekturanteile vollständig oder partiell über das Software-Component-Template spezifiziert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die oberste Schicht umfasst verschiedene Software-Component-Typen („Application Software Component“, „Actuator Software Component“, „Sensor Software Component“), die über „AUTOSAR Interface“-Ports an die darunterliegende RTE angebunden sind. Unterhalb der RTE gliedert sich die Basic Software in:</p>\n<ul class=\"fig-list\"><li>„Operating System“ (angebunden über „Standardized Interface“ zur RTE und intern über vertikales „Standardized Interface“ zu den übrigen BSW-Modulen),\n</li><li>„Services“ (mit oberem „Standardized AUTOSAR Interface“ zur RTE und unterem „Standardized Interface“),\n</li><li>„Communication“ (mit oberen und unteren „Standardized Interface“-Ports),\n</li><li>„ECU Abstraction“ (mit oberem „AUTOSAR Interface“ zur RTE und unterem „Standardized Interface“),\n</li><li>„Microcontroller Abstraction“ (über „Standardized Interface“ mit der ECU Abstraction verbunden),\n</li><li>„Complex Device Drivers“ (über „AUTOSAR Interface“ an die RTE angebunden und mit direktem Durchgriff auf die ECU-Hardware).\n</li></ul>\n<p class=\"fig-p\">Schnittstellentypen:</p>\n<ul class=\"fig-list\"><li>„AUTOSAR Interface“: Schnittstelle zwischen SWCs bzw. bestimmten BSW-Modulen und der RTE (vertikale blaue Doppelpfeile).\n</li><li>„Standardized AUTOSAR Interface“: Spezielle AUTOSAR-Schnittstelle für System-Services an die RTE (blauer Doppelpfeil).\n</li><li>„Standardized Interface“: Interne C-APIs der Basissoftware und zum Betriebssystem (orangefarbene Doppelpfeile zur RTE, grüne Verbindungspfeile innerhalb der BSW).\n</li></ul>\n<p class=\"fig-p\">Legende:</p>\n<ul class=\"fig-list\"><li>Grün vertikal gestreifte Umrandung: Software-Komponenten, die durch das Software-Component-Template vollständig beschrieben werden (Application-, Actuator- und Sensor-SWCs).\n</li><li>Blau diagonal gestreifte Umrandung: Software-Komponenten/BSW-Module, bei denen nur die „AUTOSAR Interface“-Seite im Software-Component-Template vollständig beschrieben werden kann (Services, ECU Abstraction, Complex Device Drivers).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtenarchitektur ohne explizite Ablauf- oder Sequenzpfade. Interaktionsbeziehungen sind über vertikale Doppelpfeile dargestellt:</p>\n<ul class=\"fig-list\"><li>Bidirektionale Interaktion zwischen Software-Komponenten und der RTE über AUTOSAR Interfaces.\n</li><li>Bidirektionale Kommunikation der RTE mit Services, ECU-Abstraktion und Complex Device Drivers über AUTOSAR- bzw. Standardized AUTOSAR Interfaces.\n</li><li>Direkte RTE-Verbindung zu Kommunikationsmodulen und dem Betriebssystem über Standardized Interfaces.\n</li><li>Modulübergreifende horizontale und vertikale Dienstaufrufe innerhalb der Basissoftware über Standardized Interfaces hin zum Betriebssystem und zwischen Abstraktionsschichten.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Abgrenzung des Spezifikationsbereichs für das SoftwareComponentTemplate:</p>\n<ul class=\"fig-list\"><li>Vollständig im Scope des Templates liegen Software-Komponenten der Anwendungsebene (Application, Sensor, Actuator SWCs).\n</li><li>Partiell im Scope liegen BSW-Module mit Service- oder Treibercharakter (Services, ECU Abstraction, CDD), beschränkt auf deren RTE-zugewandte AUTOSAR-Interface-Beschreibung (Service Component, ECU Abstraction Component, Complex Device Driver Component).\n</li><li>Nicht im Scope des SWC-Templates liegen reine interne BSW-Mechanismen, Kommunikationsstapel-Details, das Betriebssystem sowie MCAL-Treiber, sofern sie ausschließlich über Standardized Interfaces interagieren; diese unterliegen dem Basic Software Module Description Template (BSWMDT).\n</li></ul>"}, {"id": "FIG-f497498d989ea3dc", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm zur Einordnung des Geltungsbereichs des Software-Component-Templates (SWC-T) in die AUTOSAR-ECU-Software-Architektur. Das Modell gliedert sich vertikal von oben nach unten in die Anwendungsebene („AUTOSAR Software“), die vermittelnde Laufzeitumgebung („AUTOSAR Runtime Environment (RTE)“), die Basissoftware („Basic Software“) sowie die darunterliegende Steuergeräte-Hardware („ECU-Hardware“). Farbige Schraffur-Umrandungen und eine Legende heben hervor, welche Architekturanteile vollständig oder partiell über das Software-Component-Template spezifiziert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die oberste Schicht umfasst verschiedene Software-Component-Typen („Application Software Component“, „Actuator Software Component“, „Sensor Software Component“), die über „AUTOSAR Interface“-Ports an die darunterliegende RTE angebunden sind. Unterhalb der RTE gliedert sich die Basic Software in:</p>\n<ul class=\"fig-list\"><li>„Operating System“ (angebunden über „Standardized Interface“ zur RTE und intern über vertikales „Standardized Interface“ zu den übrigen BSW-Modulen),\n</li><li>„Services“ (mit oberem „Standardized AUTOSAR Interface“ zur RTE und unterem „Standardized Interface“),\n</li><li>„Communication“ (mit oberen und unteren „Standardized Interface“-Ports),\n</li><li>„ECU Abstraction“ (mit oberem „AUTOSAR Interface“ zur RTE und unterem „Standardized Interface“),\n</li><li>„Microcontroller Abstraction“ (über „Standardized Interface“ mit der ECU Abstraction verbunden),\n</li><li>„Complex Device Drivers“ (über „AUTOSAR Interface“ an die RTE angebunden und mit direktem Durchgriff auf die ECU-Hardware).\n</li></ul>\n<p class=\"fig-p\">Schnittstellentypen:</p>\n<ul class=\"fig-list\"><li>„AUTOSAR Interface“: Schnittstelle zwischen SWCs bzw. bestimmten BSW-Modulen und der RTE (vertikale blaue Doppelpfeile).\n</li><li>„Standardized AUTOSAR Interface“: Spezielle AUTOSAR-Schnittstelle für System-Services an die RTE (blauer Doppelpfeil).\n</li><li>„Standardized Interface“: Interne C-APIs der Basissoftware und zum Betriebssystem (orangefarbene Doppelpfeile zur RTE, grüne Verbindungspfeile innerhalb der BSW).\n</li></ul>\n<p class=\"fig-p\">Legende:</p>\n<ul class=\"fig-list\"><li>Grün vertikal gestreifte Umrandung: Software-Komponenten, die durch das Software-Component-Template vollständig beschrieben werden (Application-, Actuator- und Sensor-SWCs).\n</li><li>Blau diagonal gestreifte Umrandung: Software-Komponenten/BSW-Module, bei denen nur die „AUTOSAR Interface“-Seite im Software-Component-Template vollständig beschrieben werden kann (Services, ECU Abstraction, Complex Device Drivers).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtenarchitektur ohne explizite Ablauf- oder Sequenzpfade. Interaktionsbeziehungen sind über vertikale Doppelpfeile dargestellt:</p>\n<ul class=\"fig-list\"><li>Bidirektionale Interaktion zwischen Software-Komponenten und der RTE über AUTOSAR Interfaces.\n</li><li>Bidirektionale Kommunikation der RTE mit Services, ECU-Abstraktion und Complex Device Drivers über AUTOSAR- bzw. Standardized AUTOSAR Interfaces.\n</li><li>Direkte RTE-Verbindung zu Kommunikationsmodulen und dem Betriebssystem über Standardized Interfaces.\n</li><li>Modulübergreifende horizontale und vertikale Dienstaufrufe innerhalb der Basissoftware über Standardized Interfaces hin zum Betriebssystem und zwischen Abstraktionsschichten.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Abgrenzung des Spezifikationsbereichs für das SoftwareComponentTemplate:</p>\n<ul class=\"fig-list\"><li>Vollständig im Scope des Templates liegen Software-Komponenten der Anwendungsebene (Application, Sensor, Actuator SWCs).\n</li><li>Partiell im Scope liegen BSW-Module mit Service- oder Treibercharakter (Services, ECU Abstraction, CDD), beschränkt auf deren RTE-zugewandte AUTOSAR-Interface-Beschreibung (Service Component, ECU Abstraction Component, Complex Device Driver Component).\n</li><li>Nicht im Scope des SWC-Templates liegen reine interne BSW-Mechanismen, Kommunikationsstapel-Details, das Betriebssystem sowie MCAL-Treiber, sofern sie ausschließlich über Standardized Interfaces interagieren; diese unterliegen dem Basic Software Module Description Template (BSWMDT).\n</li></ul>"}], "trans": [{"from": "FIG-1134f09373b44cf0", "to": "FIG-25f3caeb24489c15", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-25f3caeb24489c15", "to": "FIG-f497498d989ea3dc", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
